#!/usr/bin/env python3
"""
benchmark.py

Multi-API LLM benchmark harness with SSE TTFT measurement.

Usage:
    python benchmark.py --config models.json [--output results.json] [--timeout 10] [--workers 4]
"""

import argparse
import concurrent.futures
import datetime as dt
import json
import os
import socket
import time
import urllib.error
import urllib.request
import uuid
from typing import Any, Dict, List, Optional, Tuple


PROMPT = "Reply with exactly one sentence about the color blue."


def now_iso_utc() -> str:
    return dt.datetime.now(dt.timezone.utc).isoformat()


def ms(seconds: float) -> float:
    return round(seconds * 1000.0, 3)


def load_config(path: str) -> List[Dict[str, Any]]:
    with open(path, "r", encoding="utf-8") as f:
        data = json.load(f)
    if not isinstance(data, dict) or "models" not in data or not isinstance(data["models"], list):
        raise ValueError("Config must be a JSON object with a 'models' array.")
    return data["models"]


def build_endpoint(base_url: str, api_type: str) -> str:
    base = base_url.rstrip("/")
    if api_type == "chat_completions":
        return f"{base}/v1/chat/completions"
    if api_type == "responses":
        return f"{base}/v1/responses"
    raise ValueError(f"Unsupported api_type: {api_type}")


def build_payload(model_cfg: Dict[str, Any], prompt: str) -> Dict[str, Any]:
    api_type = model_cfg["api_type"]
    payload: Dict[str, Any] = {
        "model": model_cfg["id"],
        "stream": True,
    }

    if api_type == "chat_completions":
        payload["messages"] = [{"role": "user", "content": prompt}]
    elif api_type == "responses":
        payload["input"] = prompt
    else:
        raise ValueError(f"Unsupported api_type: {api_type}")

    # Optional per-model params
    if "temperature" in model_cfg:
        payload["temperature"] = model_cfg["temperature"]
    if "max_tokens" in model_cfg:
        payload["max_tokens"] = model_cfg["max_tokens"]

    return payload


def extract_text_delta(api_type: str, event_obj: Dict[str, Any]) -> Optional[str]:
    if api_type == "chat_completions":
        choices = event_obj.get("choices")
        if not isinstance(choices, list):
            return None
        chunks: List[str] = []
        for ch in choices:
            if not isinstance(ch, dict):
                continue
            delta = ch.get("delta")
            if isinstance(delta, dict):
                content = delta.get("content")
                if isinstance(content, str):
                    chunks.append(content)
        if chunks:
            return "".join(chunks)
        return None

    if api_type == "responses":
        if event_obj.get("type") != "content_block_delta":
            return None
        delta = event_obj.get("delta")
        if isinstance(delta, dict):
            text = delta.get("text")
            if isinstance(text, str):
                return text
        return None

    return None


def make_headers(base_url: str, api_key: str) -> Dict[str, str]:
    headers = {
        "Content-Type": "application/json",
        "Accept": "text/event-stream",
        "Authorization": f"Bearer {api_key}",
    }

    # Helpful compatibility for Anthropic-style endpoints (if used).
    if "anthropic.com" in base_url:
        headers["x-api-key"] = api_key
        headers.setdefault("anthropic-version", "2023-06-01")

    return headers


def benchmark_one(model_cfg: Dict[str, Any], prompt: str, timeout_s: float) -> Dict[str, Any]:
    model_id = str(model_cfg.get("id", ""))
    api_type = str(model_cfg.get("api_type", ""))

    result = {
        "model_id": model_id,
        "api_type": api_type,
        "status": "error",
        "ttft_ms": None,
        "total_ms": None,
        "first_token": None,
        "full_response": None,
        "error": None,
    }

    t0 = time.perf_counter()
    t_start: Optional[float] = None

    try:
        if not model_id:
            raise ValueError("Missing model 'id'.")
        if api_type not in ("chat_completions", "responses"):
            raise ValueError(f"Unsupported api_type: {api_type}")
        if "base_url" not in model_cfg:
            raise ValueError(f"Model '{model_id}' missing 'base_url'.")
        if "api_key_env" not in model_cfg:
            raise ValueError(f"Model '{model_id}' missing 'api_key_env'.")

        api_key_env = model_cfg["api_key_env"]
        api_key = os.getenv(api_key_env)
        if not api_key:
            raise ValueError(f"Environment variable '{api_key_env}' is not set or empty.")

        endpoint = build_endpoint(model_cfg["base_url"], api_type)
        payload = build_payload(model_cfg, prompt)
        body = json.dumps(payload).encode("utf-8")
        headers = make_headers(model_cfg["base_url"], api_key)

        req = urllib.request.Request(endpoint, data=body, headers=headers, method="POST")

        first_token: Optional[str] = None
        first_token_time: Optional[float] = None
        full_chunks: List[str] = []

        def process_event_data(data_text: str) -> bool:
            nonlocal first_token, first_token_time
            if data_text == "[DONE]":
                return True

            try:
                obj = json.loads(data_text)
            except json.JSONDecodeError as e:
                raise ValueError(f"SSE JSON parse error: {e.msg}") from e

            delta_text = extract_text_delta(api_type, obj)
            if isinstance(delta_text, str) and delta_text != "":
                full_chunks.append(delta_text)
                if first_token is None and delta_text.strip() != "":
                    first_token = delta_text.strip()
                    first_token_time = time.perf_counter()
            return False

        t_start = time.perf_counter()
        with urllib.request.urlopen(req, timeout=timeout_s) as resp:
            # SSE parsing: gather `data:` lines until blank line (event boundary)
            data_lines: List[str] = []
            done = False

            while not done:
                raw = resp.readline()
                if not raw:
                    break  # EOF

                line = raw.decode("utf-8", errors="replace").rstrip("\r\n")

                # Keepalive/comment line
                if line.startswith(":"):
                    continue

                # Event boundary
                if line == "":
                    if data_lines:
                        data_text = "\n".join(data_lines)
                        done = process_event_data(data_text)
                        data_lines = []
                    continue

                # SSE field
                if line.startswith("data:"):
                    piece = line[5:]
                    if piece.startswith(" "):
                        piece = piece[1:]
                    data_lines.append(piece)
                # Ignore other SSE fields (event:, id:, retry:, etc.)

            # Process trailing event if stream closed without blank line
            if not done and data_lines:
                _ = process_event_data("\n".join(data_lines))

        t_end = time.perf_counter()
        full_response = "".join(full_chunks).strip()

        if first_token_time is None:
            raise ValueError("No non-empty content delta received.")

        result["status"] = "ok"
        result["ttft_ms"] = ms(first_token_time - (t_start if t_start is not None else t0))
        result["total_ms"] = ms(t_end - (t_start if t_start is not None else t0))
        result["first_token"] = first_token
        result["full_response"] = full_response
        result["error"] = None
        return result

    except urllib.error.HTTPError as e:
        elapsed = ms(time.perf_counter() - (t_start if t_start is not None else t0))
        result["total_ms"] = elapsed
        try:
            body = e.read().decode("utf-8", errors="replace")
            result["error"] = f"HTTP {e.code}: {body[:500]}"
        except Exception:
            result["error"] = f"HTTP {e.code}: {e.reason}"
        return result
    except urllib.error.URLError as e:
        elapsed = ms(time.perf_counter() - (t_start if t_start is not None else t0))
        result["total_ms"] = elapsed
        reason = getattr(e, "reason", e)
        result["error"] = f"Connection error: {reason}"
        return result
    except socket.timeout:
        elapsed = ms(time.perf_counter() - (t_start if t_start is not None else t0))
        result["total_ms"] = elapsed
        result["error"] = f"Connection timeout after {int(timeout_s * 1000)}ms"
        return result
    except TimeoutError:
        elapsed = ms(time.perf_counter() - (t_start if t_start is not None else t0))
        result["total_ms"] = elapsed
        result["error"] = f"Connection timeout after {int(timeout_s * 1000)}ms"
        return result
    except Exception as e:
        elapsed = ms(time.perf_counter() - (t_start if t_start is not None else t0))
        result["total_ms"] = elapsed
        result["error"] = str(e)
        return result


def summarize(results: List[Dict[str, Any]]) -> Dict[str, Any]:
    total = len(results)
    ok_results = [r for r in results if r.get("status") == "ok"]
    err_count = total - len(ok_results)

    ttft_pairs: List[Tuple[str, float]] = []
    for r in ok_results:
        tt = r.get("ttft_ms")
        if isinstance(tt, (int, float)):
            ttft_pairs.append((r["model_id"], float(tt)))

    avg_ttft = round(sum(v for _, v in ttft_pairs) / len(ttft_pairs), 3) if ttft_pairs else None
    fastest = min(ttft_pairs, key=lambda x: x[1])[0] if ttft_pairs else None
    slowest = max(ttft_pairs, key=lambda x: x[1])[0] if ttft_pairs else None

    return {
        "total": total,
        "ok": len(ok_results),
        "errors": err_count,
        "avg_ttft_ms": avg_ttft,
        "fastest_model": fastest,
        "slowest_model": slowest,
    }


def run_benchmark(models: List[Dict[str, Any]], timeout_s: float, workers: int) -> List[Dict[str, Any]]:
    results: List[Optional[Dict[str, Any]]] = [None] * len(models)

    with concurrent.futures.ThreadPoolExecutor(max_workers=workers) as ex:
        future_map = {
            ex.submit(benchmark_one, model_cfg, PROMPT, timeout_s): idx
            for idx, model_cfg in enumerate(models)
        }

        for fut in concurrent.futures.as_completed(future_map):
            idx = future_map[fut]
            model_cfg = models[idx]
            try:
                results[idx] = fut.result()
            except Exception as e:
                # Safety net: should almost never trigger because benchmark_one catches errors.
                results[idx] = {
                    "model_id": str(model_cfg.get("id", "")),
                    "api_type": str(model_cfg.get("api_type", "")),
                    "status": "error",
                    "ttft_ms": None,
                    "total_ms": None,
                    "first_token": None,
                    "full_response": None,
                    "error": f"Unhandled worker error: {e}",
                }

    # type ignore not needed; fill any impossible None with generic error
    out: List[Dict[str, Any]] = []
    for i, r in enumerate(results):
        if r is None:
            mc = models[i]
            out.append({
                "model_id": str(mc.get("id", "")),
                "api_type": str(mc.get("api_type", "")),
                "status": "error",
                "ttft_ms": None,
                "total_ms": None,
                "first_token": None,
                "full_response": None,
                "error": "No result produced.",
            })
        else:
            out.append(r)
    return out


def parse_args() -> argparse.Namespace:
    p = argparse.ArgumentParser(description="Benchmark multiple LLM APIs with streaming TTFT measurement.")
    p.add_argument("--config", required=True, help="Path to model config JSON")
    p.add_argument("--output", default="benchmark_results.json", help="Output JSON file path")
    p.add_argument("--timeout", type=float, default=30.0, help="Per-model timeout in seconds (default: 30)")
    p.add_argument("--workers", type=int, default=1, help="Parallel worker threads (default: 1)")
    return p.parse_args()


def main() -> int:
    args = parse_args()

    if args.workers < 1:
        print("Error: --workers must be >= 1")
        return 2
    if args.timeout <= 0:
        print("Error: --timeout must be > 0")
        return 2

    try:
        models = load_config(args.config)
    except Exception as e:
        print(f"Failed to load config: {e}")
        return 2

    run_obj: Dict[str, Any] = {
        "run_id": str(uuid.uuid4()),
        "timestamp": now_iso_utc(),
        "prompt": PROMPT,
        "results": [],
        "summary": {},
    }

    results = run_benchmark(models=models, timeout_s=args.timeout, workers=args.workers)
    run_obj["results"] = results
    run_obj["summary"] = summarize(results)

    try:
        with open(args.output, "w", encoding="utf-8") as f:
            json.dump(run_obj, f, indent=2, ensure_ascii=False)
    except Exception as e:
        print(f"Failed to write output file '{args.output}': {e}")
        return 2

    print(f"Wrote benchmark results to {args.output}")
    print(json.dumps(run_obj["summary"], indent=2))
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
